            continue;
        }
        mass.0 = base.mass;
        commands.entity(holder).remove::<CarryBaseMass>();
        info!(target: "demo::carry", ?holder, mass = base.mass,
            reason = "held_item_missing", "Holder mass restored after carry relation disappeared");
    }

